<?php declare(strict_types=1); namespace Annam; $title='Order reports & sales'; ?>
<section class="o-card"><h2>Today's sales</h2><p>Updated <?= e($sales['as_of']) ?> · excludes test payments.</p><div class="o-grid-form"><?php foreach(['order_value'=>'Orders placed today','paid_order_value'=>'Paid value of today’s orders','pending_order_value'=>'Awaiting payment','manual_receipts'=>'Manual receipts today','online_receipts'=>'Online receipts today','courier_receipts'=>'Courier receipts today','refunds'=>'Refunds today','net_receipts'=>'Net receipts today'] as $k=>$label): ?><div><small><?= e($label) ?></small><h3><?= money($sales[$k]) ?></h3></div><?php endforeach; ?></div></section>
<form class="o-card o-form"><h2>Products and quantities</h2><p>Filter by when orders were received. End time is excluded. Times use Asia/Kolkata.</p><div class="o-grid-form"><label class="o-field">From<input type="datetime-local" name="start" value="<?= e($report['start']) ?>" required></label><label class="o-field">Until<input type="datetime-local" name="end" value="<?= e($report['end']) ?>" required></label><label class="o-field">Food category<select name="meal"><option value="">All categories</option><?php foreach(['breakfast','lunch','dinner','snacks'] as $key): ?><option value="<?= e($key) ?>" <?= ($_GET['meal']??'')===$key?'selected':'' ?>><?= e(ucfirst($key)) ?></option><?php endforeach; ?></select></label><label class="o-field">Delivery date (optional)<input type="date" name="delivery_date" value="<?= e($_GET['delivery_date']??'') ?>"></label><label class="o-field">Product name or ID<input name="product" value="<?= e($_GET['product']??'') ?>"></label></div><div class="o-actions"><button class="o-btn o-btn-primary">View report</button><button class="o-btn" name="export" value="csv">Download CSV</button></div></form><p><?= e($report['order_count']) ?> orders · <?= e($report['quantity']) ?> items · items value <?= money($report['items_amount']) ?>. Order totals include one delivery fee.</p><div class="o-table-wrap"><table class="o-table"><thead><tr><th>Food category</th><th>Product</th><th>Quantity</th><th>Items amount</th></tr></thead><tbody><?php foreach($report['rows'] as $row): ?><tr><td><?= e(ucfirst($row['meal'])) ?></td><td><?= e($row['product']) ?></td><td><?= e($row['quantity']) ?></td><td><?= money($row['amount']) ?></td></tr><?php endforeach; ?><?php if(!$report['rows']): ?><tr><td colspan="4">No orders match this period.</td></tr><?php endif; ?></tbody></table></div>